## Why This Is Asked
Tests ability to design cross-store consistency, idempotent writes, conflict handling, and disaster recovery across polyglot persistence in a real-time collaboration application.

## Key Concepts
- Idempotent multi-store writes across Redis, MongoDB, Cassandra, DynamoDB
- Cross-region conflict handling with eventual consistency
- Replay/restore path and tombstone semantics for recovery

## Code Example
```javascript
// Pseudo: handle save edit across stores with client_write_id
async function saveEdit(doc, delta, clientWriteId) {
  // Redis: cache latest version atomically
  await redis.hSet(`doc:${doc.id}`, {
    content: doc.content,
    version: doc.version,
    clientWriteId
  });

  // MongoDB: upsert with revision tracking
  await db.documents.updateOne(
    { id: doc.id },
    { 
      $set: { 
        content: doc.content,
        version: doc.version,
        updatedAt: new Date(),
        clientWriteId
      }
    },
    { upsert: true }
  );

  // Cassandra: append immutable delta
  await cassandra.execute(
    'INSERT INTO document_edits (doc_id, rev, ts, user, delta, client_write_id) VALUES (?, ?, ?, ?, ?, ?)',
    [doc.id, doc.version, Date.now(), doc.userId, delta, clientWriteId]
  );

  // DynamoDB: update daily aggregates
  await dynamodb.update({
    TableName: 'daily_aggregates',
    Key: { doc_id: doc.id, date: new Date().toISOString().split('T')[0] },
    UpdateExpression: 'ADD edit_count :inc SET last_edit = :ts',
    ExpressionAttributeValues: { ':inc': 1, ':ts': Date.now() }
  });
}
```

## Why This Is Asked
Tests cross-store write/read paths, TTLs, and cache-aside logic in a beginner-friendly multi-DB setup.

## Key Concepts
- Cache-aside pattern across Redis, Cassandra, MongoDB, DynamoDB
- TTL management and LTRIM for fixed-size lists
- Upserts and simple analytics counters

## Code Example
```javascript
// Write path (pseudo)
async function onView(userId, pid) {
  const ts = Date.now();
  await cassandra.insert('view_event', {userId, pid, ts});
  await redis.lpush(`recent:${userId}`, pid);
  await redis.ltrim(`recent:${userId}`, 0, 9);
  await redis.expire(`recent:${userId}`, 7*24*3600);
  await dynamo.update('daily_views', {date: today, pid}, {increment: 1}, {upsert: true});
}

// Read path (fallback)
async function getRecent(userId) {
  let ids = await redis.lrange(`recent:${userId}`, 0, 9);
  if (!ids.length) {
    const events = await cassandra.query('SELECT pid FROM view_event WHERE userId=? ORDER BY ts DESC LIMIT 10', userId);
    ids = events.map(e => e.pid);
    await redis.rpush(`recent:${userId}`, ...ids);
    await redis.expire(`recent:${userId}`, 7*24*3600);
  }
  const products = await mongo.find('products', {_id: {$in: ids}});
  return ids.map(id => products.find(p => p._id === id));
}
```
